<?php declare(strict_types=1);require __DIR__.'/../includes/bootstrap.php';require __DIR__.'/../includes/services.php';require_student();$uid=(int)current_user()['user_id'];$ins=upsert_insight($uid);if($ins && !isset($ins['category_name'])){$cq=db()->prepare('SELECT name FROM categories WHERE category_id=? LIMIT 1');$cq->execute([(int)$ins['category_id']]);$ins['category_name']=$cq->fetchColumn();}$s=db()->prepare('SELECT i.*,c.name category_name FROM insights i LEFT JOIN categories c ON c.category_id=i.flagged_category_id WHERE i.user_id=? ORDER BY i.month_start DESC,i.version_no DESC');$s->execute([$uid]);$rows=$s->fetchAll();$pageTitle='AI Insights';$activePage='insights';require __DIR__.'/../includes/app_header.php';?><section class="page-head"><div><span class="eyebrow">INTELLIGENCE</span><h1>Monthly insights</h1><p>Reviewable suggestions generated from your own transaction history.</p></div></section><?php if($ins):?><section class="panel hero-insight"><div><span class="ai-badge">CURRENT MONTH</span><h2><?=e($ins['summary_text'])?></h2><p><?=e($ins['tip_text'])?></p></div><div class="report-note"><form method="post" action="<?=e(url("student/actions/bookmark.php"))?>" style="margin-bottom:10px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="item_type" value="insight"><input type="hidden" name="item_id" value="<?=e((string)$ins["insight_id"])?>"><button class="btn btn-ghost" type="submit">Bookmark insight</button></form><span class="muted">Flagged category</span><strong><?=e($ins['category_id']?(($ins['category_name']??'Highlighted')):'General')?></strong><small class="muted">Pattern-based review</small></div></section><?php else:?><section class="panel"><div class="empty-state"><strong>Not enough data yet.</strong><p>Add a few expenses, then revisit this page.</p></div></section><?php endif;?><section class="panel"><div class="panel-head"><div><span class="panel-kicker">HISTORY</span><h2>Previous insight runs</h2></div></div><?php foreach($rows as$r):?><article class="saved-card"><strong><?=e(date('F Y',strtotime($r['month_start'])))?></strong><p><?=e($r['summary_text'])?></p><small class="muted"><?=e($r['tip_text'])?></small></article><?php endforeach;?><?php if(!$rows):?><div class="empty-state">History will appear here.</div><?php endif;?></section><?php require __DIR__.'/../includes/footer.php';?>